height, width = 26, 29
target_color = 6
border_color = 3
corner_color = 1

# Find all connected regions
visited = [[False]*width for _ in range(height)]
regions = []

for r in range(height):
    for c in range(width):
        if grid[r][c] == target_color and not visited[r][c]:
            region = []
            queue = deque([(r,c)])
            visited[r][c] = True
            while queue:
                cr, cc = queue.popleft()
                region.append((cr, cc))
                for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                    nr, nc = cr+dr, cc+dc
                    if 0<=nr<height and 0<=nc<width and not visited[nr][nc] and grid[nr][nc]==target_color:
                        visited[nr][nc] = True
                        queue.append((nr,nc))
            min_r = min(cr for cr, cc in region)
            max_r = max(cr for cr, cc in region)
            min_c = min(cc for cr, cc in region)
            max_c = max(cc for cr, cc in region)
            regions.append((min_r, max_r, min_c, max_c))

# Create output (copy of input)
output = [[grid[r][c] for c in range(width)] for r in range(height)]

# Step 1: Draw 1-pixel border of 3 around each region
for min_r, max_r, min_c, max_c in regions:
    border_top = min_r - 1
    border_bottom = max_r + 1
    border_left = min_c - 1
    border_right = max_c + 1

    # Top border
    for c in range(min_c, max_c+1):
        if 0 <= border_top < height:
            if grid[border_top][c] != target_color:
                output[border_top][c] = border_color

    # Bottom border
    for c in range(min_c, max_c+1):
        if 0 <= border_bottom < height:
            if grid[border_bottom][c] != target_color:
                output[border_bottom][c] = border_color

    # Left border
    for r in range(min_r, max_r+1):
        if 0 <= border_left < width:
            if grid[r][border_left] != target_color:
                output[r][border_left] = border_color

    # Right border
    for r in range(min_r, max_r+1):
        if 0 <= border_right < width:
            if grid[r][border_right] != target_color:
                output[r][border_right] = border_color

# Step 2: Find max row with any border cell, then extend corner with 1s
border_rows = set()
border_cols_by_row = {}
for min_r, max_r, min_c, max_c in regions:
    border_top = min_r - 1
    border_bottom = max_r + 1
    border_left = min_c - 1
    border_right = max_c + 1

    if 0 <= border_top < height:
        border_rows.add(border_top)
        for c in range(min_c, max_c+1):
            if grid[border_top][c] != target_color:
                border_cols_by_row.setdefault(border_top, set()).add(c)
    if 0 <= border_bottom < height:
        border_rows.add(border_bottom)
        for c in range(min_c, max_c+1):
            if grid[border_bottom][c] != target_color:
                border_cols_by_row.setdefault(border_bottom, set()).add(c)
    if 0 <= border_left < width:
        for r in range(min_r, max_r+1):
            if grid[r][border_left] != target_color:
                border_cols_by_row.setdefault(r, set()).add(border_left)
    if 0 <= border_right < width:
        for r in range(min_r, max_r+1):
